public class RandomWalkExtentTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(RandomWalkExtent w) {
        return "pos=" + w.position() + " low=" + w.lowest()
                + " high=" + w.highest() + " furthest=" + w.furthest();
    }

    public static void main(String[] args) {
        try {
            RandomWalkExtent fresh = new RandomWalkExtent(7L);
            check("a fresh walker sits at the origin", "pos=0 low=0 high=0 furthest=0", describe(fresh));
            fresh.step();
            check("after one step (seed 7)", "pos=1 low=0 high=1 furthest=1", describe(fresh));
            fresh.walk(4);
            check("after five steps (seed 7)", "pos=1 low=0 high=3 furthest=3", describe(fresh));

            RandomWalkExtent low = new RandomWalkExtent(18L);
            low.walk(20);
            check("20 steps (seed 18) stray furthest downward", "pos=-2 low=-6 high=2 furthest=6", describe(low));

            RandomWalkExtent high = new RandomWalkExtent(23L);
            high.walk(20);
            check("20 steps (seed 23) stray furthest upward", "pos=4 low=-4 high=5 furthest=5", describe(high));

            RandomWalkExtent longWalk = new RandomWalkExtent(11L);
            longWalk.walk(200);
            check("200 steps (seed 11)", "pos=-26 low=-27 high=2 furthest=27", describe(longWalk));

            RandomWalkExtent a = new RandomWalkExtent(2024L);
            RandomWalkExtent b = new RandomWalkExtent(2024L);
            a.walk(20);
            b.walk(20);
            check("the same seed replays the same walk", describe(a), describe(b));

            RandomWalkExtent inv = new RandomWalkExtent(5L);
            inv.walk(50);
            check("lowest <= position <= highest", true,
                    inv.lowest() <= inv.position() && inv.position() <= inv.highest());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

