/**
 * A seeded one-dimensional random walk that remembers how far it ever strayed.
 */
public class RandomWalkExtent {

    private final java.util.Random rng;
    private int position;
    private int lowest;
    private int highest;

    public RandomWalkExtent(long seed) {
        this.rng = new java.util.Random(seed);
        this.position = 0;
        this.lowest = 0;
        this.highest = 0;
    }

    public void step() {
        position += rng.nextBoolean() ? 1 : -1;
        if (position < lowest) {
            lowest = position;
        }
        if (position > highest) {
            highest = position;
        }
    }

    public void walk(int steps) {
        for (int i = 0; i < steps; i++) {
            step();
        }
    }

    public int position() {
        return position;
    }

    public int lowest() {
        return lowest;
    }

    public int highest() {
        return highest;
    }

    public int furthest() {
        return Math.max(highest, -lowest);
    }
}
